edits.oldText:
void onSeekEnd(DragEndDetails _) {
  final hadDuration = seekDurationMs.value > 0;
  final target = seekTargetMs.value;
  seeking.value = false;
  if (hadDuration) {
    onSeek(Duration(milliseconds: target));
  }
  if (onSeekPreviewEnd != null) {
    // Keep the bottom-crumb seek preview visible briefly after release so
    // desktop tooling (which triggers drags synchronously) can capture it.
    Future<void>.delayed(const Duration(milliseconds: 250), () {
      onSeekPreviewEnd?.call();
    });
  }
}

